import sys

def solve() -> None:
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        n = int(data)
    except ValueError:
        return
    if n <= 0:
        return

    def hanoi(k: int, src: str, dst: str, aux: str) -> None:
        if k == 0:
            return
        hanoi(k - 1, src, aux, dst)
        print(f"{k} {src} {dst}")
        hanoi(k - 1, aux, dst, src)

    hanoi(n, "A", "C", "B")

if __name__ == "__main__":
    solve()
